import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.CCCdsIgc.js";const u=JSON.parse('{"title":"长任务与定时任务","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tasks.md","filePath":"guide/tasks.md"}'),i={name:"guide/tasks.md"};function o(d,t,s,n,h,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="长任务与定时任务" tabindex="-1">长任务与定时任务 <a class="header-anchor" href="#长任务与定时任务" aria-label="Permalink to &quot;长任务与定时任务&quot;">​</a></h1><h2 id="长任务" tabindex="-1">长任务 <a class="header-anchor" href="#长任务" aria-label="Permalink to &quot;长任务&quot;">​</a></h2><p>要做很久的事（整理大量文件、批量处理表格）：</p><ul><li>打开输入框下方的「<strong>长任务</strong>」开关，步数上限放宽，走到上限自动接着做；</li><li>任务每做一步就存一次，程序被关、电脑重启都不会丢。重新打开后，侧栏「任务中心」和对话里会提示「上次没做完」，点「接着做」；</li><li>悬浮球上能看到进度，鼠标停上去可以暂停、停止、插话。</li></ul><h2 id="任务中心" tabindex="-1">任务中心 <a class="header-anchor" href="#任务中心" aria-label="Permalink to &quot;任务中心&quot;">​</a></h2><p>侧栏「任务中心」：正在进行的（进度、用时、正在做什么）、上次没做完的、最近做完的。</p><h2 id="定时任务" tabindex="-1">定时任务 <a class="header-anchor" href="#定时任务" aria-label="Permalink to &quot;定时任务&quot;">​</a></h2><p>侧栏「定时任务」→「新建任务」，写一句指令再选频率：</p><table tabindex="0"><thead><tr><th>任务名</th><th>指令</th><th>频率</th></tr></thead><tbody><tr><td>整理昨天的报表</td><td>把共享盘「报表\\昨天」里的 Excel 合并成一张汇总表，放到工作区</td><td>每个工作日 08:30</td></tr><tr><td>清理临时文件</td><td>删掉工作区里 30 天前的临时文件，删之前先列出来给我看</td><td>每周一 09:00</td></tr></tbody></table><p>注意：</p><ul><li><strong>程序要开着</strong>（收在托盘里就行）。关机错过的任务，开机后补跑最近一次，超过 12 小时就跳过；</li><li>需要确认的操作会弹系统通知，可以在通知上直接点允许；<strong>5 分钟没人应答按拒绝处理</strong>；</li><li>新任务可以先勾「<strong>预演（只看不改）</strong>」跑几次，确认没问题再取消勾选；</li><li>也可以设成「文件夹里有新文件」时触发，例如共享盘出现新日报就自动汇总。</li></ul>',11)])])}const p=a(i,[["render",o]]);export{u as __pageData,p as default};
